Ui.Script:
-- ── Strings (GlobalStrings.lua, verbatim) ─────────────────────────────────────────────── local BIND_ENCHANT = "Enchanting this item will bind it to you." -- l.415 local REPLACE_ENCHANT = "Do you want to replace \"%s\" with \"%s\"?" -- l.3324 local OKAY = "Okay" local CANCEL = "Cancel" local YES = "Yes" local NO = "No"
-- ── The bind confirm — StaticPopup.lua l.1240-1251, verbatim ─────────────────────────── -- No OnCancel: declining sends nothing and needs no teardown, because the gate returned -- before BindTarget and the targeting word is still standing. The cursor simply stays up. StaticPopupDialogs["BIND_ENCHANT"] = { text = BIND_ENCHANT, button1 = OKAY, button2 = CANCEL, OnAccept = function() BindEnchant() end, timeout = 0, exclusive = 1, showAlert = 1, hideOnEscape = 1, }
-- ── The replace confirm — StaticPopup.lua l.1252-1263, verbatim ──────────────────────── -- arg1 = the enchant already on the item, arg2 = the one about to replace it, in that -- order (the fire site pushes old then new: `0x703f50(0x193, "%s%s", old, new)`). StaticPopupDialogs["REPLACE_ENCHANT"] = { text = REPLACE_ENCHANT, button1 = YES, button2 = NO, OnAccept = function() ReplaceEnchant() end, timeout = 0, exclusive = 1, showAlert = 1, hideOnEscape = 1, }
-- ── The UIParent event arms (UIParent.lua l.437-453, verbatim) ───────────────────────── function BenillaEnchantConfirmDriver_OnEvent() if event == "BIND_ENCHANT" then StaticPopup_Show("BIND_ENCHANT") elseif event == "REPLACE_ENCHANT" then StaticPopup_Show("REPLACE_ENCHANT", arg1, arg2) elseif event == "CURRENT_SPELL_CAST_CHANGED" then -- The pending cast the popups are asking about is gone (cancelled, replaced, or -- committed), so the question is moot. This is the ref's ONLY teardown for them. StaticPopup_Hide("BIND_ENCHANT") StaticPopup_Hide("REPLACE_ENCHANT") end end
